fn filter<'a>(
    b: &mut FlatBufferBuilder<'a>,
    value: &Value,
    path: &str,
) -> Result<WIPOffset<api::FilterExpr<'a>>, JsonCodecError> {
    let (kind, payload) = one_key(value, path)?;
    if kind == "none" {
        if !payload.is_object() {
            return Err(contract(format!("`{path}.none` must be an object")));
        }
        return Ok(api::FilterExpr::create(
            b,
            &api::FilterExprArgs {
                expr_type: api::FilterExprKind::NONE,
                expr: None,
            },
        ));
    }
    let (expr_type, expr) = match kind {
        "filter_and" => {
            let object = object(payload, path)?;
            let clauses = required(object, "clauses", path)?;
            let items = if is_absent_vector(clauses, &format!("{path}.clauses"))? {
                None
            } else {
                let values = array(clauses, &format!("{path}.clauses"))?;
                let items = values
                    .iter()
                    .enumerate()
                    .map(|(i, v)| filter(b, v, &format!("{path}.clauses[{i}]")))
                    .collect::<Result<Vec<_>, _>>()?;
                Some(b.create_vector(&items))
            };
            let value = api::FilterAnd::create(b, &api::FilterAndArgs { clauses: items });
            (api::FilterExprKind::FilterAnd, offset(value))
        }
        "filter_or" => {
            let object = object(payload, path)?;
            let clauses = required(object, "clauses", path)?;
            let items = if is_absent_vector(clauses, &format!("{path}.clauses"))? {
                None
            } else {
                let values = array(clauses, &format!("{path}.clauses"))?;
                let items = values
                    .iter()
                    .enumerate()
                    .map(|(i, v)| filter(b, v, &format!("{path}.clauses[{i}]")))
                    .collect::<Result<Vec<_>, _>>()?;
                Some(b.create_vector(&items))
            };
            let value = api::FilterOr::create(b, &api::FilterOrArgs { clauses: items });
            (api::FilterExprKind::FilterOr, offset(value))
        }
        "filter_not" => {
            let object = object(payload, path)?;
            let clause = filter(
                b,
                required(object, "clause", path)?,
                &format!("{path}.clause"),
            )?;
            let value = api::FilterNot::create(
                b,
                &api::FilterNotArgs {
                    clause: Some(clause),
                },
            );
            (api::FilterExprKind::FilterNot, offset(value))
        }
        "filter_comparison" => (
            api::FilterExprKind::FilterComparison,
            offset(comparison(
                b,
                object(payload, path)?,
                &format!("{path}.comparison"),
            )?),
        ),
        "filter_range" => (
            api::FilterExprKind::FilterRange,
            offset(range(b, object(payload, path)?, &format!("{path}.range"))?),
        ),
        "filter_exists" => (
            api::FilterExprKind::FilterExists,
            offset(exists(
                b,
                object(payload, path)?,
                &format!("{path}.exists"),
            )?),
        ),
        _ => return Err(contract(format!("unknown filter variant `{path}.{kind}`"))),
    };
    Ok(api::FilterExpr::create(
        b,
        &api::FilterExprArgs {
            expr_type,
            expr: Some(expr),
        },
    ))
}

