fn ranking<'a>(
    b: &mut FlatBufferBuilder<'a>,
    value: &Value,
    path: &str,
) -> Result<WIPOffset<api::RankingPolicy<'a>>, JsonCodecError> {
    let (kind, payload) = one_key(value, path)?;
    if kind == "none" {
        if !payload.is_object() {
            return Err(contract(format!("`{path}.none` must be an object")));
        }
        return Ok(api::RankingPolicy::create(
            b,
            &api::RankingPolicyArgs {
                policy_type: api::RankingPolicyKind::NONE,
                policy: None,
            },
        ));
    }
    let policy = match kind {
        "default_relevance_v1" => offset(api::DefaultRelevanceV1::create(
            b,
            &api::DefaultRelevanceV1Args {},
        )),
        "bm25_ranking" => offset(api::Bm25Ranking::create(b, &api::Bm25RankingArgs {})),
        _ => return Err(contract(format!("unknown ranking variant `{path}.{kind}`"))),
    };
    if !payload.is_object() {
        return Err(contract(format!("`{path}.{kind}` must be an object")));
    }
    Ok(api::RankingPolicy::create(
        b,
        &api::RankingPolicyArgs {
            policy_type: match kind {
                "default_relevance_v1" => api::RankingPolicyKind::DefaultRelevanceV1,
                _ => api::RankingPolicyKind::Bm25Ranking,
            },
            policy: Some(policy),
        },
    ))
}

fn query_expr<'a>(
    b: &mut FlatBufferBuilder<'a>,
    value: &Value,
    path: &str,
) -> Result<WIPOffset<api::QueryExpr<'a>>, JsonCodecError> {
    let (kind, payload) = one_key(value, path)?;
    if kind == "none" {
        if !payload.is_object() {
            return Err(contract(format!("`{path}.none` must be an object")));
        }
        return Ok(api::QueryExpr::create(
            b,
            &api::QueryExprArgs {
                expr_type: api::QueryExprKind::NONE,
                expr: None,
            },
        ));
    }
    let (expr_type, expr) = match kind {
        "term_query" => (
            api::QueryExprKind::TermQuery,
            offset(term_query(
                b,
                object(payload, path)?,
                &format!("{path}.term_query"),
            )?),
        ),
        "query_and" => {
            let object = object(payload, path)?;
            let clauses = required(object, "clauses", path)?;
            let values = if is_absent_vector(clauses, &format!("{path}.clauses"))? {
                None
            } else {
                let items = array(clauses, &format!("{path}.clauses"))?;
                let values = items
                    .iter()
                    .enumerate()
                    .map(|(i, v)| query_expr(b, v, &format!("{path}.clauses[{i}]")))
                    .collect::<Result<Vec<_>, _>>()?;
                Some(b.create_vector(&values))
            };
            let node = api::QueryAnd::create(b, &api::QueryAndArgs { clauses: values });
            (api::QueryExprKind::QueryAnd, offset(node))
        }
        "query_or" => {
            let object = object(payload, path)?;
            let clauses = required(object, "clauses", path)?;
            let values = if is_absent_vector(clauses, &format!("{path}.clauses"))? {
                None
            } else {
                let items = array(clauses, &format!("{path}.clauses"))?;
                let values = items
                    .iter()
                    .enumerate()
                    .map(|(i, v)| query_expr(b, v, &format!("{path}.clauses[{i}]")))
                    .collect::<Result<Vec<_>, _>>()?;
                Some(b.create_vector(&values))
            };
            let node = api::QueryOr::create(b, &api::QueryOrArgs { clauses: values });
            (api::QueryExprKind::QueryOr, offset(node))
        }
        "query_not" => {
            let object = object(payload, path)?;
            let clause = query_expr(
                b,
                required(object, "clause", path)?,
                &format!("{path}.clause"),
            )?;
            let node = api::QueryNot::create(
                b,
                &api::QueryNotArgs {
                    clause: Some(clause),
                },
            );
            (api::QueryExprKind::QueryNot, offset(node))
        }
        _ => return Err(contract(format!("unknown query variant `{path}.{kind}`"))),
    };
    Ok(api::QueryExpr::create(
        b,
        &api::QueryExprArgs {
            expr_type,
            expr: Some(expr),
        },
    ))
}

